insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-333', 'tec', null, 'O Suporte Avançado de Vida Pediátrico (PALS) define diretrizes específicas para a RCP em crianças. Sobre a RCP pediátrica de alta qualidade, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-334', 'tec', null, 'O manejo da obstrução de vias aéreas por corpo estranho (OVACE) em pediatria difere conforme a idade. Considerando o lactente (menor de 1 ano) consciente, com obstrução grave (incapaz de tossir ou chorar), analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-335', 'tec', null, 'Um adulto com obstrução grave de via aérea por corpo estranho fica inconsciente. A conduta correta é:', '["posicioná-lo em superfície rígida, acionar o serviço de emergência e iniciar a RCP, verificando a boca antes das ventilações e removendo o objeto se visível.","continuar as compressões abdominais com a vítima deitada.","realizar varredura digital às cegas até encontrar o objeto.","oferecer água para empurrar o objeto.","aguardar que a vítima recupere a consciência."]'::jsonb, 0, 'As compressões torácicas da RCP podem deslocar o corpo estranho; a varredura às cegas é contraindicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-336', 'tec', null, 'Na suspeita de trauma raquimedular, a técnica de mobilização da vítima em bloco, com estabilização manual da cabeça e alinhamento da coluna, para posicioná-la na prancha rígida, é o:', '["rolamento em bloco (log roll), realizado por, no mínimo, três socorristas.","transporte em cadeira.","arrasto pelas axilas, realizado por um único socorrista.","elevação pelos braços e pernas, sem estabilização cervical.","posicionamento em decúbito ventral."]'::jsonb, 0, 'Um socorrista mantém a cabeça alinhada e coordena o movimento; os demais rolam o corpo em bloco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-337', 'tec', null, 'Durante a estabilização de uma criança pequena politraumatizada em prancha longa, para manter o alinhamento neutro da coluna é necessário:', '["posicionar um coxim sob o dorso (dos ombros até a pelve), compensando o occipital proporcionalmente maior.","posicionar um coxim sob o occipital, elevando a cabeça.","fixar a criança apenas com fita adesiva, sem colar.","utilizar apenas o colar cervical, dispensando a prancha.","manter a cabeça em hiperextensão para abrir a via aérea."]'::jsonb, 0, 'O occipital proeminente da criança flexiona o pescoço em superfície plana; o coxim sob o dorso corrige essa flexão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-338', 'tec', null, 'No atendimento a um motociclista inconsciente, com capacete integral e dificuldade respiratória, que necessita de manejo da via aérea, a conduta correta é:', '["remover o capacete com a técnica de dois socorristas, mantendo a estabilização manual da coluna cervical.","remover o capacete rapidamente por um único socorrista, sem estabilização.","manter o capacete em todas as situações, mesmo com via aérea comprometida.","realizar hiperextensão do pescoço com o capacete no lugar.","aguardar a chegada ao hospital para remover o capacete."]'::jsonb, 0, 'Um socorrista estabiliza a cabeça e o pescoço enquanto o outro remove o capacete, evitando movimentos da coluna.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-339', 'tec', null, 'No controle de hemorragia externa grave em membro, quando a compressão direta não for suficiente e for necessário o torniquete, é correto:', '["aplicá-lo acima do ferimento (entre a lesão e o coração), anotar o horário de aplicação e não afrouxá-lo durante o transporte.","aplicá-lo abaixo do ferimento, para reduzir a dor.","afrouxá-lo a cada 5 minutos para irrigar o membro.","utilizar fio fino, como barbante, para maior pressão.","cobri-lo com curativo, ocultando-o da equipe que receberá a vítima."]'::jsonb, 0, 'O horário deve ficar visível; o torniquete só é retirado em ambiente hospitalar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-340', 'tec', null, 'No atendimento ao politraumatizado, o sinal clínico mais precoce e sensível do choque hipovolêmico em um adulto jovem é:', '["a taquicardia.","a hipotensão arterial (PAS < 90 mmHg).","o rebaixamento do nível de consciência.","a anúria.","a bradicardia."]'::jsonb, 0, 'A hipotensão é um sinal tardio: o organismo compensa a perda inicial com taquicardia e vasoconstrição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-341', 'tec', null, 'No atendimento pré-hospitalar a uma vítima com fratura exposta de perna, a conduta adequada é:', '["controlar o sangramento, cobrir o ferimento com gaze estéril umedecida em soro fisiológico e imobilizar o membro sem tentar reintroduzir o osso.","reintroduzir o osso no ferimento antes de imobilizar.","lavar o ferimento com água e sabão e deixá-lo descoberto.","aplicar torniquete em todas as fraturas expostas.","tracionar vigorosamente o membro até alinhar o osso."]'::jsonb, 0, 'Reintroduzir o osso leva contaminação para planos profundos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-342', 'tec', null, 'Em uma amputação traumática de dedo, o cuidado com o segmento amputado consiste em:', '["envolvê-lo em gaze umedecida com soro fisiológico, colocá-lo em saco plástico fechado e mantê-lo sobre gelo, sem contato direto com o gelo.","colocá-lo diretamente no gelo ou na água gelada.","lavá-lo com álcool 70% e mantê-lo em temperatura ambiente.","descartá-lo, pois não há possibilidade de reimplante.","mantê-lo no bolso da vítima."]'::jsonb, 0, 'O contato direto com o gelo causa lesão por congelamento e inviabiliza o reimplante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-343', 'tec', null, 'Em uma vítima com ferimento abdominal e evisceração, a conduta correta no atendimento inicial é:', '["cobrir as vísceras com compressa estéril umedecida em soro fisiológico, sem tentar reintroduzi-las.","reintroduzir as vísceras na cavidade abdominal.","cobrir as vísceras com gaze seca, pressionando-as.","lavar as vísceras com água da torneira.","oferecer líquidos à vítima."]'::jsonb, 0, 'Manter as vísceras úmidas e protegidas evita ressecamento e contaminação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-344', 'tec', null, 'Diante de uma vítima com objeto encravado (empalado) no tórax, o socorrista deve:', '["estabilizar o objeto no local com curativo volumoso, sem removê-lo.","remover o objeto imediatamente para estancar o sangramento.","empurrar o objeto para dentro, para reduzir o tamanho exposto.","girar o objeto para verificar a profundidade.","cortar o objeto rente à pele, em qualquer situação."]'::jsonb, 0, 'A remoção pode causar hemorragia grave; o objeto só é retirado em ambiente cirúrgico (exceto se obstruir a via aérea ou impedir a RCP).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-345', 'tec', null, 'Em vítima de traumatismo cranioencefálico, a presença de equimose retroauricular (sinal de Battle), equimose periorbitária bilateral (olhos de guaxinim) e saída de líquido claro pelo nariz ou ouvido sugere:', '["fratura de base de crânio.","fratura de clavícula.","trauma abdominal fechado.","lesão de medula torácica.","fratura de mandíbula isolada."]'::jsonb, 0, 'Nesses casos, evita-se a passagem de sondas pelo nariz.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-346', 'tec', null, 'A escala AVDI, utilizada para avaliação rápida do nível de consciência, classifica o paciente em:', '["Alerta, responde à Voz, responde à Dor ou Inconsciente.","Ansioso, Vigilante, Deprimido ou Irritado.","Acordado, Vocaliza, Deambula ou Imóvel.","Abertura ocular, Verbal, Dor e Inspeção.","Agitado, Violento, Desorientado ou Isolado."]'::jsonb, 0, 'A AVDI é uma avaliação neurológica simplificada, usada no exame primário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-347', 'tec', null, 'No cálculo da superfície corporal queimada em crianças pequenas, a regra dos nove do adulto precisa de adaptação porque, nelas:', '["a cabeça corresponde a uma proporção maior da superfície corporal, e os membros inferiores, a uma proporção menor.","a cabeça corresponde a uma proporção menor da superfície corporal.","não é possível estimar a superfície queimada.","o tronco representa 50% do corpo.","todas as regiões têm o mesmo percentual."]'::jsonb, 0, 'Em lactentes, a cabeça corresponde a cerca de 18%; por isso se usam tabelas adaptadas, como a de Lund-Browder.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-348', 'tec', null, 'Na queimadura química por substância líquida na pele, a primeira conduta é:', '["remover as roupas contaminadas e irrigar abundantemente a área com água corrente.","aplicar uma substância neutralizante imediatamente.","cobrir com pomada e não lavar.","aplicar gelo diretamente sobre a pele.","esfregar a área com pano seco."]'::jsonb, 0, 'A irrigação abundante e prolongada remove o agente; se for pó seco, ele deve ser escovado antes da irrigação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-349', 'tec', null, 'Nas queimaduras elétricas, um aspecto importante para a avaliação e o monitoramento da vítima é que:', '["as lesões internas podem ser muito mais extensas que as lesões visíveis na pele, havendo risco de arritmias cardíacas.","a lesão é sempre superficial, sem risco sistêmico.","não há necessidade de monitorização cardíaca.","a vítima pode ser tocada antes do desligamento da fonte de energia.","a gravidade é medida apenas pela extensão da pele queimada."]'::jsonb, 0, 'A corrente percorre os tecidos profundos; também há risco de mioglobinúria e insuficiência renal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-350', 'tec', null, 'Ao chegar ao local de um acidente em que a vítima ainda está em contato com fio elétrico, a primeira conduta do socorrista é:', '["garantir a segurança da cena, desligando a fonte de energia ou acionando a concessionária, antes de tocar na vítima.","puxar a vítima pelos braços imediatamente.","afastar o fio com um objeto metálico.","iniciar compressões torácicas com a vítima ainda no fio.","jogar água sobre a vítima."]'::jsonb, 0, 'A segurança do socorrista é prioridade: tocar a vítima energizada transforma o socorrista em nova vítima.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-351', 'tec', null, 'No atendimento à vítima de afogamento em parada respiratória, a prioridade inicial é:', '["a ventilação, pois a parada decorre principalmente da hipóxia.","a desfibrilação imediata, antes de qualquer ventilação.","a compressão abdominal para retirar a água dos pulmões.","o aquecimento da vítima antes da reanimação.","aguardar a drenagem espontânea da água."]'::jsonb, 0, 'No afogamento, a causa é hipóxica; as manobras para "retirar água" atrasam a reanimação e não são recomendadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-352', 'tec', null, 'Na vítima de hipotermia acidental, consciente, a conduta inicial adequada é:', '["retirar as roupas molhadas, abrigar a vítima em local aquecido e promover reaquecimento gradual com cobertores.","massagear vigorosamente as extremidades.","oferecer bebida alcoólica para aquecer.","colocá-la imediatamente em banho muito quente.","mantê-la em movimento, caminhando."]'::jsonb, 0, 'Massagem e reaquecimento brusco podem desencadear arritmias e queimaduras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-353', 'tec', null, 'Na intoxicação por inseticidas organofosforados, são sinais característicos:', '["miose, sialorreia, sudorese, broncorreia e bradicardia.","midríase, pele seca e taquicardia.","hipertermia e pele vermelha e seca.","icterícia e colúria.","hiperglicemia e poliúria."]'::jsonb, 0, 'É uma síndrome colinérgica; o antídoto utilizado é a atropina, conforme prescrição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-354', 'tec', null, 'Em caso de intoxicação, o serviço de informação toxicológica (Disque-Intoxicação) pode ser acionado gratuitamente pelo número:', '["0800-722-6001.","192.","193.","190.","136."]'::jsonb, 0, 'O Disque-Intoxicação, da ANVISA, conecta aos Centros de Informação e Assistência Toxicológica (CIATox). 192 é o SAMU; 193, os bombeiros; 136, o Disque Saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-355', 'tec', null, 'Uma criança picada por escorpião apresenta dor local intensa. A orientação correta é:', '["levá-la imediatamente a um serviço de saúde para avaliação e observação, pois crianças têm maior risco de complicações graves.","fazer torniquete acima do local.","cortar e sugar o local da picada.","aplicar querosene ou álcool no local.","aguardar em casa até a dor passar."]'::jsonb, 0, 'O tratamento inclui analgesia e, conforme a gravidade, soro antiescorpiônico; crianças pequenas têm risco de complicações sistêmicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-356', 'tec', null, 'Em acidente com abelhas, os ferrões devem ser removidos:', '["raspando-os com uma lâmina ou cartão, sem pinçá-los.","com pinça, apertando a bolsa de veneno.","apertando a pele ao redor para extrair o ferrão.","não devem ser removidos.","com fita adesiva, puxando com força."]'::jsonb, 0, 'Pinçar o ferrão comprime a glândula e injeta mais veneno. Múltiplas picadas ou sinais de alergia exigem atendimento de urgência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-357', 'tec', null, 'Sobre o reconhecimento da anafilaxia, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-358', 'tec', null, 'Um paciente chega à unidade com crise asmática, dispneia e sibilos. Enquanto aguarda a avaliação médica, a conduta adequada da equipe de enfermagem é:', '["mantê-lo sentado, com a cabeceira elevada, monitorar a saturação e preparar a oxigenoterapia e o broncodilatador conforme protocolo e prescrição.","deitá-lo em decúbito dorsal horizontal.","oferecer água gelada para aliviar a falta de ar.","administrar sedativo para reduzir a ansiedade.","colocá-lo em Trendelenburg."]'::jsonb, 0, 'A posição sentada favorece a expansão torácica; sedativos podem deprimir a respiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-359', 'tec', null, 'No paciente com suspeita de infarto agudo do miocárdio que aguarda atendimento, a equipe de enfermagem deve:', '["manter o paciente em repouso, monitorizado, com acesso venoso, e realizar o eletrocardiograma em até 10 minutos da chegada.","estimular a deambulação para aliviar a dor.","oferecer refeição para evitar hipoglicemia.","aguardar a dor passar antes de realizar o ECG.","administrar oxigênio em alto fluxo a todos, independentemente da saturação."]'::jsonb, 0, 'O oxigênio está indicado quando há hipoxemia (SpO2 < 90%); o ECG precoce define a conduta de reperfusão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-360', 'tec', null, 'Na suspeita de AVC, uma informação essencial que deve ser obtida e registrada pela equipe é:', '["o horário de início dos sintomas ou o último momento em que o paciente foi visto sem sintomas.","o tipo sanguíneo do paciente.","o histórico de vacinação.","a profissão do paciente.","a data da última consulta odontológica."]'::jsonb, 0, 'A janela de tempo define a possibilidade de trombólise e de outras terapias de reperfusão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-361', 'tec', null, 'Um paciente diabético é encontrado inconsciente, com glicemia capilar de 35 mg/dL. Nesse caso:', '["não se deve oferecer nada por via oral, pelo risco de aspiração; o tratamento é a glicose endovenosa ou o glucagon, conforme prescrição.","deve-se oferecer suco de laranja na boca.","deve-se administrar insulina regular.","deve-se aguardar a recuperação espontânea.","deve-se colocar açúcar sob a língua e deixar a vítima em decúbito dorsal."]'::jsonb, 0, 'Paciente inconsciente não deve receber nada por via oral.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-362', 'tec', null, 'Diante de uma pessoa que desmaia (síncope) e recupera rapidamente a consciência, sem sinais de trauma, a conduta inicial é:', '["mantê-la deitada, com os membros inferiores elevados, afrouxar roupas apertadas e observar os sinais vitais.","levantá-la imediatamente e fazê-la caminhar.","oferecer água enquanto ainda está deitada e sonolenta.","dar tapas no rosto para mantê-la acordada.","colocá-la sentada com a cabeça entre os joelhos por 1 hora."]'::jsonb, 0, 'A elevação dos membros inferiores favorece o retorno venoso; a causa da síncope deve ser investigada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-363', 'tec', null, 'Na epistaxe anterior, a orientação adequada é:', '["manter a pessoa sentada, com a cabeça levemente inclinada para a frente, e comprimir as asas do nariz por cerca de 10 minutos.","inclinar a cabeça para trás, para o sangue não escorrer.","deitar a pessoa em decúbito dorsal.","assoar o nariz com força para retirar os coágulos.","introduzir algodão seco profundamente na narina."]'::jsonb, 0, 'Inclinar a cabeça para trás faz o sangue escorrer para a faringe, com risco de vômito e aspiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-364', 'tec', null, 'Em suspeita de luxação de ombro, a conduta do socorrista no atendimento inicial é:', '["imobilizar o membro na posição em que foi encontrado, sem tentar reduzir a luxação, e encaminhar ao serviço.","tentar recolocar a articulação no lugar imediatamente.","aplicar calor local e massagear.","mobilizar o membro ativamente para avaliar a amplitude.","tracionar o braço com força."]'::jsonb, 0, 'A redução deve ser feita em ambiente adequado, após avaliação e exame de imagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-365', 'tec', null, 'No método START de triagem em incidentes com múltiplas vítimas, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-366', 'tec', null, 'O transporte seguro de pacientes pediátricos em ambulâncias requer equipamentos e cuidados específicos. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-367', 'tec', null, 'No Suporte Avançado de Vida Pediátrico, a ressuscitação volêmica inicial recomendada para uma criança com choque hipovolêmico ou séptico é:', '["bolus de solução cristaloide isotônica (SF 0,9% ou Ringer lactato) de 20 mL/kg, em infusão rápida, com reavaliação após cada bolus.","solução glicosada 5% em infusão contínua.","aguardar o acesso central para iniciar o vasopressor.","albumina 10 mL/kg em 60 minutos, como primeira escolha.","restrição hídrica até a chegada do pediatra."]'::jsonb, 0, 'Após cada bolus, reavaliam-se perfusão, frequência cardíaca e sinais de sobrecarga hídrica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-368', 'tec', null, 'O Triângulo de Avaliação Pediátrica (TAP) é uma ferramenta visual e auditiva rápida para identificar a criança em risco. Seus três componentes são:', '["aparência, trabalho (esforço) respiratório e circulação da pele.","via aérea, respiração e circulação.","nível de consciência, frequência cardíaca e enchimento capilar.","sinais vitais, saturação e pressão arterial.","respiração, pulso e coloração, sem considerar o esforço respiratório."]'::jsonb, 0, 'O TAP é feito sem tocar a criança, nos primeiros segundos do contato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-369', 'tec', null, 'No trauma pediátrico, as lesões abdominais são comuns e potencialmente graves. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-370', 'tec', null, 'Uma vítima de ferimento penetrante no tórax apresenta ferida que "aspira" ar a cada inspiração. No atendimento pré-hospitalar, a conduta indicada é:', '["cobrir a ferida com curativo oclusivo, conforme protocolo (por exemplo, curativo de três pontas ou dispositivo valvulado), e monitorar sinais de pneumotórax hipertensivo.","deixar a ferida aberta para drenar o ar.","introduzir gaze profundamente na ferida.","deitar a vítima sobre o lado não lesado e comprimir o tórax.","realizar compressões torácicas imediatamente."]'::jsonb, 0, 'O curativo valvulado permite a saída e impede a entrada de ar; a piora respiratória pode indicar pneumotórax hipertensivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-371', 'tec', null, 'Em um paciente com trauma torácico, a presença de dispneia progressiva, ausência de murmúrio vesicular de um lado, turgência jugular, hipotensão e desvio da traqueia para o lado oposto sugere:', '["pneumotórax hipertensivo.","contusão muscular simples.","fratura de clavícula isolada.","crise de ansiedade.","pneumonia."]'::jsonb, 0, 'É emergência com risco de morte, exigindo descompressão imediata pela equipe médica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-372', 'tec', null, 'Os valores de referência de frequência cardíaca de um lactente em repouso situam-se, aproximadamente, entre:', '["100 e 160 bpm.","60 e 100 bpm.","40 e 60 bpm.","160 e 220 bpm.","70 e 90 bpm."]'::jsonb, 0, 'Os valores de referência variam com a idade; usar parâmetros do adulto em crianças leva a erros de avaliação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-373', 'tec', null, 'Uma criança apresenta crise convulsiva generalizada que dura mais de 5 minutos. Essa situação:', '["caracteriza emergência (estado de mal epiléptico), exigindo tratamento medicamentoso imediato conforme prescrição, além de suporte de vias aéreas.","é esperada e não exige intervenção.","deve ser tratada com banho frio.","exige que se introduza um objeto na boca da criança.","deve ser observada por 1 hora antes de qualquer conduta."]'::jsonb, 0, 'Crises prolongadas aumentam o risco de lesão neurológica; os benzodiazepínicos são a primeira linha.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-374', 'tec', null, 'Durante um parto iminente no ambiente pré-hospitalar, após o nascimento de um recém-nascido vigoroso, a conduta adequada é:', '["secar e aquecer o recém-nascido, colocá-lo em contato pele a pele com a mãe e clampear o cordão após 1 a 3 minutos.","tracionar o cordão para acelerar a saída da placenta.","dar banho imediato no recém-nascido.","cortar o cordão imediatamente, sem clampeamento.","suspender o recém-nascido pelos pés e dar palmadas."]'::jsonb, 0, 'Não se traciona o cordão; a placenta sai espontaneamente, e o transporte é feito com a mãe e o bebê aquecidos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-375', 'tec', null, 'Na RCP realizada por leigos não treinados, a orientação atual é:', '["realizar apenas compressões torácicas contínuas (RCP somente com as mãos) até a chegada do socorro.","não iniciar nenhuma manobra.","realizar apenas ventilações boca a boca.","realizar compressões abdominais.","aguardar a chegada do DEA antes de qualquer manobra."]'::jsonb, 0, 'A RCP apenas com compressões aumenta a chance de o leigo agir e é eficaz nos primeiros minutos da PCR no adulto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-376', 'tec', null, 'No atendimento a vítima com suspeita de intermação (hipertermia por exposição ao calor), com pele quente, confusão mental e temperatura elevada, a conduta inicial é:', '["remover a vítima para local fresco, retirar roupas em excesso e iniciar o resfriamento com água e ventilação, acionando o serviço de emergência.","oferecer bebida alcoólica gelada.","cobrir a vítima com cobertor.","administrar antitérmico por via oral à vítima confusa.","manter a vítima ao sol até a chegada do socorro."]'::jsonb, 0, 'Na intermação, o resfriamento rápido é a medida mais importante; vítimas confusas não devem receber nada por via oral.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-377', 'tec', null, 'Em uma vítima de trauma, o exame primário segue a sequência XABCDE. A letra D corresponde à:', '["avaliação neurológica (nível de consciência, pupilas e déficits motores).","desfibrilação.","drenagem torácica.","dosagem de glicemia, exclusivamente.","descompressão gástrica."]'::jsonb, 0, 'D (disability): avaliação neurológica, com escala de Glasgow ou AVDI e exame das pupilas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-378', 'tec', null, 'A letra E do exame primário do trauma (XABCDE) refere-se a:', '["exposição da vítima, com controle do ambiente para prevenir a hipotermia.","estabilização da coluna cervical.","eletrocardiograma imediato.","entubação orotraqueal.","encaminhamento ao centro cirúrgico."]'::jsonb, 0, 'A vítima é exposta para identificar lesões e, em seguida, coberta para evitar a perda de calor.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-379', 'tec', null, 'No atendimento à vítima de queimadura extensa, a conduta inicial adequada inclui:', '["interromper o processo de queimadura, remover roupas e adornos não aderidos, cobrir com material limpo e seco e prevenir a hipotermia.","romper as bolhas e aplicar pomadas caseiras.","resfriar com gelo toda a superfície queimada.","retirar à força os tecidos aderidos à pele.","aplicar manteiga sobre as lesões."]'::jsonb, 0, 'Em grandes queimados, o resfriamento extenso pode causar hipotermia; anéis e relógios devem ser retirados antes do edema.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-380', 'tec', null, 'Durante a RCP no ambiente hospitalar, o carrinho de emergência deve ser:', '["conferido periodicamente, com materiais e medicamentos organizados, dentro da validade e lacrado conforme a rotina da instituição.","conferido apenas quando ocorre uma PCR.","mantido trancado com chave, longe da unidade.","utilizado para guardar materiais de outros setores.","abastecido somente uma vez por ano."]'::jsonb, 0, 'A checagem regular garante que nada falte no momento da emergência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-381', 'tec', null, 'No paciente vítima de trauma com suspeita de lesão de coluna, a abertura das vias aéreas deve ser feita, preferencialmente, pela manobra de:', '["tração da mandíbula (jaw thrust), mantendo a coluna cervical alinhada.","inclinação da cabeça e elevação do queixo (head tilt-chin lift).","hiperextensão cervical.","rotação lateral da cabeça.","flexão do pescoço sobre o tórax."]'::jsonb, 0, 'A inclinação da cabeça é evitada no trauma, pois movimenta a coluna cervical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-382', 'tec', null, 'Ao atender uma pessoa com dor torácica, sudorese e náuseas, o técnico de enfermagem deve, de imediato:', '["comunicar o enfermeiro ou o médico, aferir sinais vitais e preparar o eletrocardiograma, mantendo o paciente em repouso.","orientar o paciente a aguardar a vez na fila.","oferecer analgésico por conta própria.","liberar o paciente para casa com orientação de repouso.","solicitar que o paciente suba as escadas até o consultório."]'::jsonb, 0, 'A dor torácica é situação de prioridade na classificação de risco, pela possibilidade de síndrome coronariana aguda.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-383', 'tec', null, 'São considerados sinais de certeza da gravidez:', '["batimentos cardíacos fetais e movimentos fetais percebidos pelo examinador, além da visualização do embrião ou feto na ultrassonografia.","atraso menstrual e náuseas matinais.","aumento do volume das mamas e polaciúria.","aumento do volume abdominal e ganho de peso.","teste de gravidez de farmácia positivo, isoladamente."]'::jsonb, 0, 'Atraso menstrual e náuseas são sinais de presunção; as alterações uterinas e o hCG são sinais de probabilidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-384', 'tec', null, 'Sobre os exames recomendados na primeira consulta de pré-natal, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-385', 'tec', null, 'Uma gestante apresenta teste rápido para sífilis reagente na consulta de pré-natal. Segundo as recomendações do Ministério da Saúde, a conduta é:', '["iniciar o tratamento com penicilina benzatina na própria unidade, sem aguardar o resultado do teste não treponêmico, e investigar e tratar a parceria sexual.","aguardar o resultado do VDRL para decidir o tratamento.","encaminhar a gestante ao hospital para tratamento após o parto.","tratar apenas se houver lesões visíveis.","repetir o teste rápido apenas no terceiro trimestre."]'::jsonb, 0, 'O tratamento imediato previne a sífilis congênita; o VDRL é coletado para acompanhamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-386', 'tec', null, 'Uma gestante de 22 semanas, sem comprovação de vacinação contra difteria e tétano, chega à sala de vacinas. A conduta adequada é:', '["iniciar o esquema com dT e garantir a aplicação de uma dose de dTpa, completando três doses conforme o intervalo recomendado.","contraindicar qualquer vacina durante a gestação.","aplicar apenas a vacina tríplice viral.","aguardar o puerpério para iniciar o esquema.","aplicar a dTpa somente se a gestante tiver mais de 35 anos."]'::jsonb, 0, 'A dTpa deve ser feita a partir da 20ª semana em cada gestação; o restante do esquema é completado com dT.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-387', 'tec', null, 'São sinais de início do trabalho de parto ativo:', '["contrações uterinas regulares e dolorosas, com modificações progressivas do colo uterino.","contrações irregulares que cedem com o repouso.","aumento da frequência urinária no terceiro trimestre.","movimentos fetais intensos isoladamente.","dor lombar leve sem contrações."]'::jsonb, 0, 'Contrações irregulares que cedem com repouso sugerem pródromos (falso trabalho de parto).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-388', 'tec', null, 'Ao atender uma gestante com rotura de membranas, a observação de líquido amniótico esverdeado indica:', '["presença de mecônio, exigindo avaliação imediata da vitalidade fetal.","líquido normal, sem necessidade de comunicação.","sangramento materno.","infecção urinária.","início do puerpério."]'::jsonb, 0, 'O líquido normal é claro; o mecônio pode indicar sofrimento fetal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-389', 'tec', null, 'O período puerperal é dividido em fases distintas que requerem acompanhamento da equipe de enfermagem. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-390', 'tec', null, 'A sequência normal de evolução dos lóquios no puerpério é:', '["rubros, serosos (fuscos) e brancos (alba).","brancos, serosos e rubros.","serosos, rubros e brancos.","rubros, brancos e serosos.","purulentos, rubros e serosos."]'::jsonb, 0, 'Lóquios com odor fétido ou retorno do sangramento intenso devem ser comunicados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-391', 'tec', null, 'No puerpério imediato após parto vaginal, a puérpera apresenta sangramento abundante e útero amolecido e aumentado à palpação. A primeira suspeita e a conduta inicial de enfermagem são:', '["atonia uterina; realizar massagem uterina, comunicar imediatamente a equipe e monitorar os sinais vitais.","involução uterina normal; orientar repouso.","infecção puerperal; aguardar a febre.","retenção urinária; oferecer líquidos.","mastite; aplicar compressas."]'::jsonb, 0, 'A atonia é a principal causa de hemorragia pós-parto; o útero contraído (globo de segurança de Pinard) indica boa involução.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-392', 'tec', null, 'A assistência ao parto deve seguir as boas práticas para garantir segurança e bem-estar materno e fetal. Considerando as Diretrizes Nacionais de Assistência ao Parto Normal, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-393', 'tec', null, 'Durante o período expulsivo do parto, a manobra de Kristeller (pressão no fundo uterino para acelerar a saída do feto):', '["não deve ser realizada, por estar associada a riscos para a mãe e o bebê.","é recomendada rotineiramente em primigestas.","deve ser feita pelo técnico de enfermagem sempre que o parto demorar.","é indicada para prevenir lacerações perineais.","é obrigatória quando a parturiente está cansada."]'::jsonb, 0, 'As diretrizes de assistência ao parto não recomendam a manobra de Kristeller.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-394', 'tec', null, 'Uma puérpera em amamentação apresenta mama dolorosa, vermelha e quente, com febre (mastite). A orientação correta é:', '["manter a amamentação, com esvaziamento frequente da mama, e procurar avaliação para tratamento.","suspender definitivamente a amamentação na mama afetada.","enfaixar a mama para diminuir a produção de leite.","aplicar compressas muito quentes por horas seguidas.","descartar todo o leite produzido."]'::jsonb, 0, 'O esvaziamento da mama faz parte do tratamento; o leite não prejudica o bebê.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-395', 'tec', null, 'Para a prevenção e o tratamento de fissuras mamilares, a orientação mais importante é:', '["corrigir a pega e o posicionamento do bebê durante a mamada.","suspender a amamentação até a cicatrização total.","lavar os mamilos com sabão antes de cada mamada.","usar pomadas e cremes em todas as mamadas.","oferecer mamadeira nos intervalos."]'::jsonb, 0, 'A pega incorreta é a principal causa de fissura; passar o próprio leite nos mamilos após a mamada pode ajudar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-396', 'tec', null, 'Sobre a ordenha e o armazenamento domiciliar do leite materno, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-397', 'tec', null, 'A RDC nº 171/2006 da ANVISA regula o funcionamento dos Bancos de Leite Humano (BLH). Sobre o processamento do leite humano, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-398', 'tec', null, 'O transporte do Leite Humano Ordenhado Cru (LHOC) da residência da doadora até o Banco de Leite Humano deve ser feito:', '["em caixa isotérmica com gelo reciclável, garantindo que o leite chegue congelado ou refrigerado (no máximo 5 °C).","em temperatura ambiente, por até 3 horas.","após fervura do leite pela doadora.","no veículo particular da doadora, sem controle de temperatura.","em sacos plásticos comuns, sem refrigeração."]'::jsonb, 0, 'O controle de temperatura preserva a qualidade do leite até o processamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-399', 'tec', null, 'A biossegurança no Banco de Leite Humano visa proteger o produto e os profissionais. De acordo com a RDC nº 171/2006, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-400', 'tec', null, 'No Método Canguru, a posição canguru consiste em:', '["manter o recém-nascido de baixo peso em contato pele a pele, na posição vertical, junto ao peito dos pais.","manter o recém-nascido na incubadora sem contato com a família.","colocar o recém-nascido em decúbito ventral no berço comum.","embrulhar o recém-nascido em cobertores grossos, longe da mãe.","manter o bebê no colo apenas durante a amamentação."]'::jsonb, 0, 'A posição canguru favorece o controle térmico, o vínculo e o aleitamento materno.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-401', 'tec', null, 'O alojamento conjunto é o sistema hospitalar em que:', '["o recém-nascido sadio permanece ao lado da mãe 24 horas por dia, no mesmo ambiente, até a alta.","o recém-nascido fica no berçário e é levado à mãe apenas para mamar.","a mãe e o bebê ficam em andares diferentes.","o bebê é cuidado exclusivamente pela equipe de enfermagem.","a visita do pai é proibida."]'::jsonb, 0, 'Favorece o aleitamento materno, o vínculo e o aprendizado dos cuidados com o bebê.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-402', 'tec', null, 'Na assistência ao recém-nascido em fototerapia, é cuidado de enfermagem:', '["proteger os olhos com venda adequada, expor a maior área possível de pele e manter a hidratação e o aleitamento.","cobrir todo o corpo do recém-nascido com roupas.","aplicar óleos e cremes na pele antes da fototerapia.","suspender a amamentação durante todo o tratamento.","manter o aparelho desligado durante a noite."]'::jsonb, 0, 'A troca de decúbito e o controle de temperatura também fazem parte dos cuidados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-403', 'tec', null, 'São sinais de hipoglicemia no recém-nascido:', '["tremores, hipotonia, sucção débil, apneia e hipotermia.","choro forte e vigoroso.","ganho de peso acelerado.","fezes amareladas.","coloração rosada e boa sucção."]'::jsonb, 0, 'Os sinais são inespecíficos; recém-nascidos de mães diabéticas e prematuros têm maior risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-404', 'tec', null, 'O reflexo do recém-nascido em que, ao tocar o canto da boca, ele vira a cabeça na direção do estímulo e abre a boca, é o reflexo de:', '["busca (procura).","Moro.","preensão palmar.","Babinski.","marcha."]'::jsonb, 0, 'O reflexo de busca, junto com o de sucção, é importante para a amamentação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-405', 'tec', null, 'Durante a assistência ao recém-nascido, a equipe de enfermagem participa da triagem neonatal. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-406', 'tec', null, 'Na pesagem do lactente na consulta de puericultura, o procedimento correto é:', '["pesar a criança despida, em balança pediátrica tarada (zerada), e registrar o peso na Caderneta da Criança.","pesar a criança vestida e descontar 1 kg.","pesar a mãe com a criança no colo e subtrair o peso estimado da mãe.","pesar apenas a cada 6 meses.","pesar a criança após a mamada, vestida com fralda."]'::jsonb, 0, 'O registro nas curvas de crescimento permite identificar desvios precocemente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-407', 'tec', null, 'São sinais de que o bebê em aleitamento materno exclusivo está recebendo leite suficiente:', '["ganho de peso adequado e pelo menos seis fraldas molhadas por dia, com urina clara.","choro após todas as mamadas.","mamadas a cada 6 horas, no máximo.","fezes endurecidas e escuras.","urina concentrada e escura."]'::jsonb, 0, 'A avaliação inclui também a observação da mamada e o acompanhamento do crescimento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-408', 'tec', null, 'No Brasil, é contraindicação à amamentação:', '["mãe infectada pelo HIV.","mãe com resfriado comum.","mãe com mamilos planos.","mãe vacinada contra influenza.","mãe com mastite."]'::jsonb, 0, 'Também contraindicam o aleitamento a infecção pelo HTLV e o uso de alguns medicamentos; resfriado e mastite não impedem a amamentação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-409', 'tec', null, 'Sobre o preparo do soro de reidratação oral (SRO), é correto orientar a família a:', '["dissolver um envelope em 1 litro de água filtrada ou fervida (já fria) e utilizar a solução em até 24 horas.","dissolver o envelope em meio copo de água.","ferver a solução após o preparo.","adicionar açúcar ou sal para melhorar o sabor.","guardar a solução por 3 dias na geladeira."]'::jsonb, 0, 'A diluição correta é fundamental: concentrada demais pode agravar a desidratação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-410', 'tec', null, 'Segundo o calendário de vacinação da criança, aos 2 meses de idade são aplicadas as vacinas:', '["pentavalente, VIP, pneumocócica 10-valente e rotavírus.","BCG e hepatite B.","tríplice viral e febre amarela.","meningocócica C e hepatite A.","DTP e varicela."]'::jsonb, 0, 'Aos 3 e 5 meses, aplica-se a meningocócica C; aos 4 meses, repetem-se pentavalente, VIP, pneumocócica e rotavírus.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-411', 'tec', null, 'No calendário do PNI, a vacina meningocócica ACWY é indicada para adolescentes na faixa etária de:', '["11 a 14 anos.","1 a 4 anos.","15 a 19 anos, exclusivamente.","20 a 29 anos.","acima de 60 anos."]'::jsonb, 0, 'A meningocócica ACWY amplia a proteção contra os sorogrupos A, C, W e Y.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-412', 'tec', null, 'Segundo o PNI, a vacina tríplice viral (sarampo, caxumba e rubéola) para adultos sem comprovação vacinal é indicada da seguinte forma:', '["2 doses para pessoas até 29 anos e 1 dose para pessoas de 30 a 59 anos.","1 dose para todas as idades, inclusive acima de 60 anos.","3 doses para pessoas de 20 a 29 anos.","dose única apenas para gestantes.","não é indicada para adultos."]'::jsonb, 0, 'Pessoas com esquema completo comprovado não precisam ser revacinadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-413', 'tec', null, 'Para a pessoa idosa, a vacina indicada anualmente, nas campanhas do Ministério da Saúde, é a:', '["vacina influenza.","BCG.","tríplice viral.","rotavírus.","HPV."]'::jsonb, 0, 'A pessoa idosa também deve manter a dT atualizada e, em situações específicas, receber vacinas pneumocócicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-414', 'tec', null, 'Uma criança de 8 meses comparece à sala de vacinas com a terceira dose da pentavalente em atraso há dois meses. A conduta correta é:', '["aplicar a dose em atraso, sem reiniciar o esquema, pois as doses já aplicadas são consideradas válidas.","reiniciar todo o esquema vacinal.","aguardar a próxima campanha.","aplicar duas doses no mesmo dia para compensar o atraso.","contraindicar a vacina por causa do atraso."]'::jsonb, 0, 'No PNI, não se reinicia esquema interrompido; completa-se o que falta, respeitando os intervalos mínimos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-415', 'tec', null, 'Sobre a aplicação simultânea de vacinas, é correto afirmar:', '["a maioria das vacinas do calendário pode ser administrada no mesmo dia, em locais anatômicos diferentes.","nunca se deve aplicar mais de uma vacina no mesmo dia.","as vacinas devem ser misturadas na mesma seringa para reduzir as picadas.","vacinas injetáveis e orais não podem ser feitas juntas.","todas as vacinas vivas devem ser aplicadas com 6 meses de intervalo."]'::jsonb, 0, 'Exceção importante: em menores de 2 anos, febre amarela e tríplice viral não devem ser aplicadas no mesmo dia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-416', 'tec', null, 'Em crianças menores de 2 anos, o local preferencial para aplicação de vacinas por via intramuscular é:', '["o músculo vasto lateral da coxa.","o músculo deltoide.","a região dorsoglútea.","a região ventroglútea, exclusivamente.","o antebraço."]'::jsonb, 0, 'A partir de 2 anos, o deltoide passa a ser utilizado com frequência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-417', 'tec', null, 'Sobre a conservação de vacinas na sala de vacinação (rede de frio), analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-418', 'tec', null, 'Ao abrir um frasco multidose de vacina, o técnico deve:', '["registrar a data e o horário de abertura no frasco e respeitar o prazo de validade após a abertura indicado pelo fabricante.","utilizar o frasco até acabar, independentemente do tempo.","guardar o frasco aberto na geladeira doméstica da unidade, sem identificação.","descartar o frasco imediatamente após a primeira dose.","deixar o frasco fora da caixa térmica durante todo o turno."]'::jsonb, 0, 'O prazo de uso após a abertura varia entre as vacinas (horas ou semanas).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-419', 'tec', null, 'Na vacinação de rotina em sala de vacinas, segundo o Manual de Normas e Procedimentos do PNI:', '["não é necessário o uso rotineiro de luvas, exceto quando o vacinador tiver lesões nas mãos ou houver risco de contato com fluidos.","o uso de luvas estéreis é obrigatório em todas as aplicações.","não é necessária a higiene das mãos entre os atendimentos.","o mesmo par de luvas pode ser usado em vários pacientes.","a vacina deve ser aplicada sobre a roupa do paciente."]'::jsonb, 0, 'A higiene das mãos antes e depois de cada atendimento é a principal medida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-420', 'tec', null, 'Antes da aplicação de vacinas em sala de vacinação da Atenção Básica, quanto ao preparo da pele, recomenda-se:', '["dispensar a antissepsia com álcool; se a pele estiver visivelmente suja, lavar com água e sabão.","aplicar álcool iodado em todos os casos.","aplicar clorexidina degermante e esperar 10 minutos.","fazer tricotomia no local.","aplicar éter para desengordurar a pele."]'::jsonb, 0, 'O álcool é reservado a situações específicas, como a vacinação em ambiente hospitalar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-421', 'tec', null, 'Uma criança regurgitou logo após receber a vacina rotavírus. A conduta correta, segundo o PNI, é:', '["não repetir a dose, considerando a criança vacinada.","repetir a dose imediatamente.","repetir a dose após 24 horas.","aplicar a vacina por via intramuscular.","reiniciar todo o esquema aos 4 meses."]'::jsonb, 0, 'A vacina rotavírus não deve ser repetida em caso de regurgitação ou vômito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-422', 'tec', null, 'O esquema básico da vacina hepatite B para adultos não vacinados é de:', '["três doses, com intervalo de 1 mês entre a 1ª e a 2ª e de 6 meses entre a 1ª e a 3ª.","dose única.","duas doses com intervalo de 1 ano.","quatro doses anuais.","reforço a cada 10 anos, sem esquema básico."]'::jsonb, 0, 'Esquema 0, 1 e 6 meses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-423', 'tec', null, 'Segundo o PNI, a mulher que amamenta criança menor de 6 meses e precisa receber a vacina febre amarela deve ser orientada a:', '["suspender o aleitamento materno por 10 dias após a vacinação, mantendo a produção de leite por ordenha e descarte.","interromper definitivamente a amamentação.","amamentar normalmente, sem qualquer cuidado.","receber duas doses da vacina no mesmo dia.","aplicar a vacina no bebê também."]'::jsonb, 0, 'A medida reduz o risco de transmissão do vírus vacinal ao lactente pelo leite.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-424', 'tec', null, 'São eventos supostamente atribuíveis à vacinação ou imunização (ESAVI) comuns e geralmente leves:', '["dor, vermelhidão e endurecimento no local da aplicação e febre baixa.","anafilaxia e convulsões em todos os vacinados.","paralisia permanente.","perda auditiva súbita.","insuficiência renal aguda."]'::jsonb, 0, 'Eventos graves são raros e devem ser notificados e investigados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-425', 'tec', null, 'A imunização passiva ocorre quando o indivíduo:', '["recebe anticorpos prontos, como soros e imunoglobulinas.","recebe vacina com antígenos para produzir os próprios anticorpos.","adquire a doença e se recupera.","recebe vacina de vírus vivo atenuado.","recebe reforço vacinal."]'::jsonb, 0, 'A imunização passiva tem efeito imediato, porém temporário; a ativa (vacina ou doença) gera memória imunológica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-426', 'tec', null, 'No transporte de vacinas em caixa térmica, as bobinas reutilizáveis de gelo devem ser ambientadas antes do uso para:', '["evitar o congelamento das vacinas pelo contato com bobinas em temperatura muito baixa.","aumentar o tempo de congelamento das vacinas.","dispensar o uso do termômetro.","permitir o transporte das vacinas fora da faixa de temperatura.","reduzir o peso da caixa."]'::jsonb, 0, 'As vacinas devem permanecer entre +2 °C e +8 °C; o congelamento inativa vacinas como a pentavalente e a hepatite B.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-427', 'tec', null, 'Em relação à vacina BCG, é correto afirmar:', '["deve ser adiada em recém-nascidos com peso inferior a 2.000 g.","é aplicada por via intramuscular no glúteo.","deve ser repetida se não houver cicatriz em todas as crianças.","é contraindicada para todos os filhos de mães com hepatite B.","é aplicada aos 12 meses."]'::jsonb, 0, 'A BCG é intradérmica, na inserção inferior do deltoide direito; a ausência de cicatriz não indica revacinação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-428', 'tec', null, 'No atendimento de enfermagem no puerpério, a orientação sobre a higiene perineal da puérpera deve incluir:', '["higiene com água corrente e sabão neutro e troca frequente dos absorventes.","duchas vaginais diárias.","uso de antisséptico na vagina várias vezes ao dia.","evitar a higiene até a retirada dos pontos.","uso de absorventes internos nos primeiros dias."]'::jsonb, 0, 'Medidas simples de higiene previnem infecção da episiorrafia e endometrite.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-429', 'tec', null, 'A Infecção Relacionada à Assistência à Saúde no puerpério, como a endometrite, é uma complicação grave. Considerando as medidas de prevenção no pós-parto, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-430', 'tec', null, 'Uma nutriz no puerpério imediato relata dor intensa e ingurgitamento mamário no terceiro dia pós-parto. A orientação prioritária de enfermagem é:', '["orientar a livre demanda, assegurando a pega correta, com massagem suave e ordenha de alívio antes ou durante a mamada, se necessário.","restringir a ingestão de líquidos para diminuir a produção de leite.","recomendar a extração completa do leite e compressas quentes após cada mamada.","suspender a amamentação por 24 horas e enfaixar as mamas.","orientar banhos quentes demorados sobre as mamas antes da mamada."]'::jsonb, 0, 'O esvaziamento adequado das mamas é a base do manejo; enfaixar e restringir líquidos não são recomendados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-431', 'tec', null, 'A pega correta é essencial para o sucesso da amamentação. Indica pega INADEQUADA:', '["o bebê sugar apenas o mamilo, com lábios voltados para dentro e bochechas encovadas.","a boca do bebê bem aberta, abocanhando o mamilo e grande parte da aréola.","o lábio inferior do bebê voltado para fora e o queixo tocando a mama.","a sucção lenta e profunda, sendo possível ouvir o bebê deglutir.","o corpo do bebê voltado para a mãe, com barriga encostada na barriga."]'::jsonb, 0, 'Bochechas encovadas e lábios invertidos indicam pega incorreta, com risco de fissuras e baixa transferência de leite.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-432', 'tec', null, 'O teste da linguinha (avaliação do frênulo lingual), obrigatório nas maternidades, tem como objetivo:', '["identificar alterações do frênulo da língua que podem prejudicar a amamentação.","avaliar a acuidade visual.","detectar cardiopatias congênitas.","avaliar a audição.","identificar doenças metabólicas."]'::jsonb, 0, 'A anquiloglossia pode dificultar a pega e a sucção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-433', 'tec', null, 'No recém-nascido a termo, o valor aproximado esperado do perímetro cefálico ao nascer é de:', '["33 a 35 cm.","25 a 27 cm.","40 a 42 cm.","45 a 50 cm.","20 a 22 cm."]'::jsonb, 0, 'O acompanhamento do perímetro cefálico nas curvas ajuda a identificar micro e macrocefalia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-434', 'tec', null, 'No acompanhamento do crescimento infantil na Caderneta da Criança, a medida do comprimento em menores de 2 anos deve ser feita:', '["com a criança deitada, em infantômetro (régua antropométrica horizontal).","com a criança em pé, encostada na parede.","com fita métrica sobre a roupa.","apenas a partir dos 2 anos.","com a criança no colo da mãe."]'::jsonb, 0, 'A partir dos 2 anos, mede-se a altura com a criança em pé, no estadiômetro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-435', 'tec', null, 'Durante a consulta de puericultura, os responsáveis perguntam sobre a alimentação do bebê de 4 meses em aleitamento materno exclusivo. A orientação correta é:', '["manter o aleitamento materno exclusivo até os 6 meses, sem oferecer água, chás ou outros alimentos.","introduzir papinhas de frutas a partir dos 4 meses.","oferecer água e chás nos dias quentes.","substituir parte das mamadas por fórmula.","suspender a amamentação noturna."]'::jsonb, 0, 'O leite materno supre as necessidades de água e nutrientes até os 6 meses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-436', 'tec', null, 'A vacina contra o HPV, no calendário do PNI para meninas e meninos de 9 a 14 anos, tem como principal objetivo prevenir:', '["o câncer do colo do útero e outros cânceres e lesões associados ao HPV.","a hepatite B.","a infecção pelo HIV.","a sífilis congênita.","a tuberculose."]'::jsonb, 0, 'A vacinação antes do início da vida sexual é mais eficaz.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-437', 'tec', null, 'Em relação à vacina contra varicela no calendário infantil, é correto afirmar que:', '["é aplicada aos 15 meses (como tetraviral) e há uma segunda dose aos 4 anos.","é aplicada ao nascer.","é aplicada apenas em adultos.","é inativada e pode ser aplicada em gestantes.","é feita por via oral."]'::jsonb, 0, 'A varicela é vacina de vírus vivo atenuado, contraindicada na gestação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-438', 'tec', null, 'No acompanhamento de uma gestante, o técnico de enfermagem observa pressão arterial de 150 x 100 mmHg, cefaleia intensa e visão turva. A conduta adequada é:', '["comunicar imediatamente o enfermeiro ou o médico, pois os sinais sugerem pré-eclâmpsia grave.","orientar repouso em casa e retorno em 30 dias.","oferecer analgésico e liberar a gestante.","repetir a pressão no mês seguinte.","registrar os dados sem comunicar a equipe."]'::jsonb, 0, 'Cefaleia, alterações visuais e dor epigástrica com hipertensão são sinais de gravidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-439', 'tec', null, 'A tuberculose é doença de notificação compulsória, e o tratamento diretamente observado favorece a adesão e a cura. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-440', 'tec', null, 'Paciente internado com tuberculose pulmonar bacilífera precisa ser levado ao setor de radiologia. Durante o transporte, a conduta correta é:', '["o paciente deve usar máscara cirúrgica, e os profissionais que o acompanham, máscara PFF2/N95.","o paciente deve usar máscara PFF2/N95, e o profissional, nenhuma proteção.","o transporte é proibido em qualquer situação.","basta o uso de luvas pelo profissional.","o paciente pode transitar sem máscara, pois o corredor é ventilado."]'::jsonb, 0, 'A máscara cirúrgica no paciente reduz a emissão de partículas; a PFF2 protege o profissional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-441', 'tec', null, 'O Teste Rápido Molecular para Tuberculose (TRM-TB), utilizado no diagnóstico, tem como vantagem:', '["detectar o Mycobacterium tuberculosis e, ao mesmo tempo, a resistência à rifampicina, com resultado em poucas horas.","dispensar a coleta de qualquer amostra.","substituir a vacinação BCG.","detectar a infecção latente com uma gota de sangue do dedo.","diagnosticar todas as doenças respiratórias."]'::jsonb, 0, 'O exame é realizado em amostra de escarro, e o resultado orienta rapidamente o tratamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-442', 'tec', null, 'Sobre a transmissão da hanseníase, é correto afirmar:', '["ocorre pelas vias aéreas superiores, por contato próximo e prolongado com pessoa com a forma multibacilar sem tratamento.","ocorre pelo toque nas manchas de pele.","ocorre por objetos de uso pessoal, como talheres e roupas.","o paciente deve ficar isolado durante todo o tratamento.","o paciente continua transmitindo a doença durante todo o tratamento."]'::jsonb, 0, 'Após o início do tratamento, o paciente deixa de transmitir; não há indicação de isolamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-443', 'tec', null, 'Durante o tratamento da hanseníase com poliquimioterapia, o paciente queixa-se de escurecimento da pele. Esse efeito está relacionado, principalmente, ao uso da:', '["clofazimina.","rifampicina.","dapsona.","isoniazida.","amoxicilina."]'::jsonb, 0, 'O escurecimento é esperado e regride após o término do tratamento; a rifampicina pode deixar a urina avermelhada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-444', 'tec', null, 'Diante do aumento de casos febris no território durante o período de chuvas, a equipe investiga arboviroses como dengue, zika e chikungunya. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-445', 'tec', null, 'Segundo o Ministério da Saúde, no manejo do paciente adulto com dengue sem sinais de alarme, em acompanhamento ambulatorial, a hidratação oral recomendada é de aproximadamente:', '["60 mL/kg/dia, sendo cerca de um terço com soro de reidratação oral.","10 mL/kg/dia.","500 mL por dia, no total.","200 mL/kg/dia de água pura.","a hidratação oral é contraindicada."]'::jsonb, 0, 'A hidratação deve começar já na suspeita; o paciente é orientado sobre os sinais de alarme para retorno imediato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-446', 'tec', null, 'A infecção pelo vírus Zika na gestação é motivo de preocupação porque:', '["pode causar microcefalia e outras alterações congênitas no feto.","provoca apenas sintomas respiratórios leves.","não pode ser transmitida para o feto.","é prevenida pela vacina BCG.","é transmitida apenas por transfusão de sangue."]'::jsonb, 0, 'O Zika também pode ser transmitido por via sexual, por isso se recomenda o uso de preservativo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-447', 'tec', null, 'No ciclo silvestre da febre amarela, os vetores são mosquitos dos gêneros:', '["Haemagogus e Sabethes.","Anopheles e Culex.","Lutzomyia e Phlebotomus.","Triatoma e Panstrongylus.","Aedes albopictus e Culex quinquefasciatus, exclusivamente."]'::jsonb, 0, 'No ciclo urbano, o vetor é o Aedes aegypti; a vacinação é a principal medida de prevenção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-448', 'tec', null, 'A leishmaniose visceral é transmitida pela picada de:', '["flebotomíneos (mosquito-palha), tendo o cão como principal reservatório no ambiente urbano.","Aedes aegypti.","carrapatos.","pulgas de ratos.","barbeiros."]'::jsonb, 0, 'Os sinais incluem febre prolongada, emagrecimento e aumento do fígado e do baço.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-449', 'tec', null, 'A doença de Chagas pode ser transmitida, além da via vetorial (barbeiro), por via:', '["oral, pela ingestão de alimentos contaminados, como caldo de cana ou açaí.","respiratória, por gotículas.","sexual, exclusivamente.","picada do Aedes aegypti.","contato com urina de ratos."]'::jsonb, 0, 'Também ocorre por transfusão, transplante e transmissão vertical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-450', 'tec', null, 'A esquistossomose mansônica é adquirida principalmente pelo:', '["contato da pele com água doce contaminada por cercárias liberadas por caramujos do gênero Biomphalaria.","consumo de carne de porco malcozida.","contato com urina de ratos.","picada de mosquito.","contato com saliva de cães."]'::jsonb, 0, 'Saneamento básico e educação em saúde são medidas de controle.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-451', 'tec', null, 'Sobre a hepatite C, é correto afirmar:', '["é transmitida principalmente pelo sangue, não há vacina e existe tratamento com alta taxa de cura.","é transmitida apenas pela via fecal-oral.","é prevenida pela vacina hepatite B.","não tem tratamento.","é transmitida pelo mosquito Aedes."]'::jsonb, 0, 'Compartilhar seringas, alicates e lâminas são formas de exposição; a testagem é oferecida na Atenção Básica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-452', 'tec', null, 'A Profilaxia Pré-Exposição ao HIV (PrEP) é indicada para:', '["pessoas não infectadas pelo HIV com risco aumentado de exposição, que usam o medicamento antes de uma possível exposição.","pessoas já infectadas pelo HIV, como tratamento.","pessoas que tiveram exposição de risco nas últimas 72 horas, exclusivamente.","recém-nascidos de mães HIV negativas.","qualquer pessoa, dispensando o uso de preservativo para outras IST."]'::jsonb, 0, 'Após exposição de risco, usa-se a PEP (profilaxia pós-exposição), iniciada em até 72 horas. A PrEP não protege contra outras IST.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-453', 'tec', null, 'A sífilis primária caracteriza-se por:', '["úlcera única, geralmente indolor, de bordas endurecidas (cancro duro), no local de entrada da bactéria.","lesões nas palmas das mãos e plantas dos pés.","lesões cardiovasculares e neurológicas.","febre alta e tosse produtiva.","verrugas em couve-flor na região genital."]'::jsonb, 0, 'Na sífilis secundária, surgem lesões de pele, inclusive palmoplantares; a terciária pode acometer sistema nervoso e cardiovascular.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-454', 'tec', null, 'Na abordagem de pessoas com Infecções Sexualmente Transmissíveis (IST), é fundamental:', '["orientar, testar e tratar também as parcerias sexuais, além de reforçar o uso de preservativo.","tratar apenas o paciente sintomático, sem comunicar a parceria.","suspender a testagem para HIV e sífilis.","orientar abstinência sexual permanente.","aguardar resultados de cultura para iniciar qualquer orientação."]'::jsonb, 0, 'Sem o tratamento das parcerias, ocorrem reinfecções e a manutenção da cadeia de transmissão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-455', 'tec', null, 'Na doença meningocócica, a quimioprofilaxia é indicada:', '["aos contatos próximos do caso, como moradores do mesmo domicílio, de forma oportuna.","a toda a população do município.","apenas ao paciente, após a alta.","somente aos profissionais de saúde que não usaram EPI e tiveram contato casual.","a qualquer pessoa que tenha passado pela unidade de saúde."]'::jsonb, 0, 'A quimioprofilaxia (em geral, rifampicina) é indicada para contatos próximos, conforme protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-456', 'tec', null, 'Diante de um caso suspeito de sarampo, uma medida de controle importante no território é:', '["a vacinação de bloqueio dos contatos suscetíveis, preferencialmente em até 72 horas após a exposição.","aguardar a confirmação laboratorial para qualquer ação.","isolar o paciente em enfermaria comum, sem precauções.","aplicar BCG nos contatos.","tratar todos os contatos com antibiótico."]'::jsonb, 0, 'O sarampo é altamente contagioso, transmitido por aerossóis; a notificação é imediata.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-457', 'tec', null, 'A coqueluche caracteriza-se por:', '["tosse em crises (paroxística), seguida de inspiração ruidosa (guincho), podendo haver vômitos após a tosse.","febre alta com manchas avermelhadas que começam na face.","dor articular intensa.","lesões vesiculares em diferentes estágios.","rigidez de nuca e vômitos em jato."]'::jsonb, 0, 'É mais grave em lactentes; a vacinação da gestante com dTpa protege o recém-nascido.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-458', 'tec', null, 'Na varicela, as lesões de pele caracterizam-se por:', '["polimorfismo, com máculas, pápulas, vesículas e crostas presentes ao mesmo tempo, acompanhadas de prurido.","lesões todas no mesmo estágio de evolução.","manchas sem prurido e sem sensibilidade.","lesões apenas nas palmas e plantas.","placas brancas na mucosa oral."]'::jsonb, 0, 'A transmissão ocorre por aerossóis e contato; o paciente internado fica em precaução para aerossóis e contato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-459', 'tec', null, 'No contexto das síndromes gripais, a etiqueta respiratória inclui:', '["cobrir a boca e o nariz ao tossir ou espirrar com o antebraço ou lenço descartável e higienizar as mãos em seguida.","tossir sobre as mãos e cumprimentar as pessoas normalmente.","usar o mesmo lenço de pano o dia inteiro.","evitar a higiene das mãos para não ressecar a pele.","frequentar ambientes fechados e aglomerados."]'::jsonb, 0, 'Medidas simples reduzem a transmissão de vírus respiratórios.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-460', 'tec', null, 'O tétano acidental caracteriza-se por:', '["contraturas musculares, trismo (dificuldade de abrir a boca) e espasmos, sem transmissão de pessoa a pessoa.","febre hemorrágica transmitida por mosquito.","transmissão pela tosse.","lesões de pele com perda de sensibilidade.","diarreia aguda."]'::jsonb, 0, 'É causado pela toxina do Clostridium tetani, que penetra em ferimentos; previne-se com vacinação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-461', 'tec', null, 'Na profilaxia da raiva humana após mordedura por cão, um aspecto que pode modificar a conduta é:', '["a possibilidade de observar o animal por 10 dias.","a cor do pelo do animal.","o horário da mordedura.","o tamanho do animal.","a idade do animal, exclusivamente."]'::jsonb, 0, 'Se o cão ou gato for observável e permanecer sadio por 10 dias, o esquema pode ser encerrado, conforme protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-462', 'tec', null, 'A notificação de um caso suspeito de doença de notificação compulsória deve ser realizada:', '["a partir da suspeita, sem aguardar a confirmação diagnóstica.","somente após a confirmação laboratorial.","apenas se o paciente evoluir para óbito.","somente pelo médico infectologista.","apenas uma vez por ano, em relatório consolidado."]'::jsonb, 0, 'A notificação precoce permite a adoção oportuna de medidas de controle.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-463', 'tec', null, 'Sobre a hipertensão arterial sistêmica, é correto orientar o paciente que:', '["a doença costuma ser silenciosa (assintomática), por isso o tratamento e o acompanhamento devem ser contínuos.","a medicação pode ser suspensa quando não houver sintomas.","a dor de cabeça é sempre o primeiro sinal da doença.","a hipertensão não tem relação com o consumo de sal.","a pressão deve ser medida apenas quando houver mal-estar."]'::jsonb, 0, 'A ausência de sintomas favorece o abandono do tratamento; a adesão previne AVC, infarto e doença renal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-464', 'tec', null, 'Para pessoas com hipertensão, a recomendação de consumo de sal de cozinha é de, no máximo, cerca de:', '["5 g por dia.","20 g por dia.","15 g por dia.","1 colher de sopa por refeição.","não há limite recomendado."]'::jsonb, 0, 'Cerca de 5 g de sal equivalem a 2 g de sódio; alimentos ultraprocessados são grandes fontes de sódio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-465', 'tec', null, 'São sinais e sintomas clássicos do diabetes mellitus descompensado:', '["poliúria, polidipsia, polifagia e perda de peso.","bradicardia e hipotermia.","ganho de peso rápido e sonolência apenas.","manchas na pele sem sensibilidade.","tosse seca e febre."]'::jsonb, 0, 'São os chamados "4 Ps".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-466', 'tec', null, 'Hálito com odor de frutas (cetônico), respiração profunda e rápida, desidratação e glicemia muito elevada sugerem:', '["cetoacidose diabética.","hipoglicemia.","crise hipertensiva.","intoxicação alcoólica isolada.","crise de asma."]'::jsonb, 0, 'É uma emergência metabólica, mais comum no diabetes tipo 1.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-467', 'tec', null, 'Na avaliação dos pés da pessoa com diabetes, o teste com monofilamento de 10 g tem como objetivo:', '["avaliar a sensibilidade protetora plantar, identificando neuropatia.","medir a pressão arterial do tornozelo.","verificar a temperatura dos pés.","avaliar a força muscular.","medir o tamanho do pé para escolha do calçado."]'::jsonb, 0, 'A perda da sensibilidade protetora aumenta o risco de úlceras e amputações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-468', 'tec', null, 'Em relação à hipoglicemia e à hiperglicemia no paciente diabético, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-469', 'tec', null, 'No paciente com doença pulmonar obstrutiva crônica (DPOC) em exacerbação, a oxigenoterapia deve ser administrada com cautela, em baixo fluxo e com metas de saturação mais baixas, porque:', '["altas concentrações de oxigênio podem levar à retenção de gás carbônico e à depressão respiratória em alguns pacientes.","o oxigênio provoca broncoespasmo.","pacientes com DPOC não precisam de oxigênio.","o oxigênio piora a tosse.","a saturação desses pacientes deve ser mantida em 100%."]'::jsonb, 0, 'Em geral, a meta de saturação é de 88% a 92%, conforme prescrição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-470', 'tec', null, 'Paciente com insuficiência cardíaca deve ser orientado a se pesar diariamente e a procurar a unidade em caso de:', '["ganho rápido de peso (por exemplo, mais de 1 a 2 kg em poucos dias), inchaço e piora da falta de ar.","perda de 200 g em uma semana.","aumento do apetite.","melhora da disposição.","diminuição do inchaço nas pernas."]'::jsonb, 0, 'O ganho rápido de peso sugere retenção de líquidos e descompensação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-471', 'tec', null, 'Sobre os cuidados com a fístula arteriovenosa (FAV) do paciente em hemodiálise, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-472', 'tec', null, 'Em relação à detecção precoce do câncer de mama, o Ministério da Saúde e o INCA orientam que a mulher:', '["conheça o próprio corpo e procure a unidade de saúde ao perceber alterações nas mamas, sem que o autoexame substitua o exame clínico e a mamografia.","realize apenas o autoexame mensal, dispensando a mamografia.","faça mamografia mensal a partir dos 20 anos.","procure atendimento somente se houver dor.","evite tocar as mamas."]'::jsonb, 0, 'A estratégia de "conhecer o corpo" favorece a identificação de sinais suspeitos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-473', 'tec', null, 'No manuseio de excretas (urina, fezes, vômito) de pacientes em quimioterapia antineoplásica, nas primeiras 48 horas após a administração, o profissional deve:', '["utilizar luvas e avental, por causa da possível presença de resíduos dos quimioterápicos.","dispensar o uso de EPI, pois não há risco.","descartar as excretas sem qualquer cuidado especial.","utilizar apenas máscara cirúrgica.","manusear as excretas somente após 30 dias."]'::jsonb, 0, 'Os quimioterápicos e seus metabólitos são eliminados nas excretas e podem expor o profissional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-474', 'tec', null, 'Associe os termos às suas definições.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-475', 'tec', null, 'Diante de um paciente agitado e verbalmente agressivo no serviço de saúde, a primeira abordagem da equipe deve ser:', '["a abordagem verbal (técnicas de desescalada), com postura calma, ambiente seguro e escuta, reservando a contenção para situações em que outras medidas falharem.","a contenção mecânica imediata.","a administração de sedativo sem prescrição.","o confronto verbal para impor limites.","deixar o paciente sozinho em sala fechada."]'::jsonb, 0, 'A contenção é medida de exceção, com prescrição, monitoramento e registro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-476', 'tec', null, 'Ao orientar um paciente que iniciou o uso de antidepressivo, é correto informar que:', '["o efeito terapêutico costuma surgir após algumas semanas de uso contínuo, e o medicamento não deve ser interrompido sem orientação.","o efeito é imediato, já no primeiro dia.","o medicamento pode ser suspenso assim que o paciente se sentir melhor.","pode ser tomado com bebidas alcoólicas sem risco.","deve ser usado apenas nos dias de tristeza."]'::jsonb, 0, 'A interrupção abrupta pode causar sintomas de descontinuação e recaída.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-477', 'tec', null, 'Na avaliação do risco de suicídio, o fator de risco considerado mais importante é:', '["a tentativa de suicídio prévia.","a idade inferior a 10 anos.","o hábito de praticar esportes.","a boa rede de apoio familiar.","a religiosidade."]'::jsonb, 0, 'Transtornos mentais, uso de álcool e drogas, isolamento e acesso a meios letais também elevam o risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-478', 'tec', null, 'Durante uma visita domiciliar, o técnico acompanha um idoso de 78 anos com várias doenças crônicas, em uso de diversos medicamentos e com episódios recentes de esquecimento e instabilidade ao caminhar. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-479', 'tec', null, 'Sobre a incontinência urinária na pessoa idosa, é correto afirmar:', '["não é consequência normal do envelhecimento e deve ser investigada, pois pode ter tratamento.","é parte natural da velhice e não deve ser abordada.","ocorre apenas em mulheres.","deve ser tratada exclusivamente com fraldas.","indica sempre infecção urinária."]'::jsonb, 0, 'A abordagem inclui investigação de causas, exercícios, ajustes de medicamentos e tratamento específico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-480', 'tec', null, 'Na doença de Alzheimer, a manifestação inicial mais característica é:', '["a perda de memória para fatos recentes.","a perda súbita da consciência.","a paralisia de um lado do corpo.","a febre persistente.","a perda da memória de fatos da infância, com memória recente preservada."]'::jsonb, 0, 'A doença é progressiva; a família e o cuidador devem ser orientados e apoiados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-481', 'tec', null, 'Na orientação aos pais sobre prevenção de acidentes domésticos com crianças pequenas, é correto recomendar:', '["manter produtos de limpeza e medicamentos fora do alcance das crianças, em local trancado, e usar os cabos das panelas virados para dentro do fogão.","guardar produtos de limpeza em garrafas de refrigerante.","deixar a criança sozinha na banheira por curtos períodos.","manter janelas sem telas ou grades em andares altos.","colocar o bebê para dormir em decúbito ventral."]'::jsonb, 0, 'O bebê deve dormir de barriga para cima, para prevenir a morte súbita.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-482', 'tec', null, 'Durante a assistência à saúde do adolescente, a equipe desenvolve ações de promoção, prevenção e acolhimento, considerando os princípios éticos e os direitos assegurados. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-483', 'tec', null, 'Durante ações de saúde sexual e reprodutiva, a equipe de enfermagem orienta sobre os métodos contraceptivos e apoia a decisão informada dos usuários. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-484', 'tec', null, 'Diante da notificação de casos de doenças transmissíveis no município, a equipe revisa as precauções. Analise: I. O sarampo é doença bacteriana transmitida pela água contaminada. II. A vacinação é a principal medida de prevenção do sarampo. III. A meningite meningocócica exige precauções para gotículas. Está correto o que se afirma em:', '["II e III apenas.","I, II e III.","II apenas.","I apenas.","III apenas."]'::jsonb, 0, 'O sarampo é doença viral, transmitida por aerossóis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-485', 'tec', null, 'Durante a busca ativa de sintomáticos respiratórios na comunidade, o técnico identifica um morador com tosse há 4 semanas, febre vespertina e emagrecimento. A conduta adequada é:', '["orientar e encaminhar o morador à UBS para avaliação e coleta de escarro, comunicando a equipe.","orientar que a tosse é passageira e não requer avaliação.","oferecer xarope caseiro e retornar em 6 meses.","notificar a polícia.","realizar a coleta de sangue no domicílio para diagnóstico de tuberculose."]'::jsonb, 0, 'Tosse por 3 semanas ou mais com febre e emagrecimento é sugestiva de tuberculose.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-486', 'tec', null, 'Ao orientar a comunidade sobre a prevenção da leptospirose em período de enchentes, é correto recomendar:', '["evitar contato com água e lama de enchentes e usar botas e luvas na limpeza, além de limpar os locais com água sanitária.","nadar em águas de enchente para se refrescar.","acumular lixo nos quintais.","deixar alimentos expostos para os roedores.","consumir alimentos que tiveram contato com a água da enchente."]'::jsonb, 0, 'A leptospirose é transmitida pela urina de roedores presente na água e na lama.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-487', 'tec', null, 'No contexto da vigilância em saúde, a investigação de um caso suspeito de doença transmissível tem como objetivos:', '["identificar a fonte de infecção, os contatos e adotar medidas de controle oportunas.","punir o paciente que transmitiu a doença.","substituir o tratamento do paciente.","divulgar o nome do paciente na comunidade.","aguardar o fim do surto para iniciar as ações."]'::jsonb, 0, 'A investigação é sigilosa e orienta as medidas para interromper a transmissão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-488', 'tec', null, 'Em uma unidade de internação, um paciente com diarreia por Clostridioides difficile deve ser mantido em:', '["precaução de contato, com higiene das mãos com água e sabão.","precaução para aerossóis.","precaução para gotículas, exclusivamente.","nenhuma precaução além da padrão.","isolamento reverso."]'::jsonb, 0, 'O álcool não elimina os esporos do C. difficile.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-489', 'tec', null, 'A escabiose (sarna) em uma família exige como conduta:', '["tratar simultaneamente todos os contactantes e lavar roupas de cama e de uso pessoal.","tratar apenas a pessoa com mais lesões.","isolar o paciente em hospital.","aplicar antibiótico endovenoso em todos.","aguardar a cura espontânea."]'::jsonb, 0, 'O tratamento simultâneo evita a reinfestação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-490', 'tec', null, 'Sobre a pediculose (piolho), é correto orientar:', '["examinar e tratar os contactantes, fazer a remoção das lêndeas com pente fino e evitar o compartilhamento de pentes, toucas e bonés.","raspar a cabeça de todas as crianças da escola.","afastar a criança da escola por 30 dias.","usar inseticida doméstico no couro cabeludo.","não há necessidade de examinar os contactantes."]'::jsonb, 0, 'O tratamento deve seguir orientação profissional; produtos inadequados podem causar intoxicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-491', 'tec', null, 'No paciente em uso de anticoncepcional oral combinado, uma orientação importante é:', '["tomar o comprimido diariamente, no mesmo horário, e usar preservativo para prevenção de IST.","tomar o comprimido apenas antes das relações sexuais.","suspender o anticoncepcional ao usar preservativo.","dobrar a dose diariamente para aumentar a eficácia.","tomar o comprimido somente em dias alternados."]'::jsonb, 0, 'O esquecimento de comprimidos reduz a eficácia; deve-se seguir a orientação da bula ou do profissional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-492', 'tec', null, 'No acolhimento a uma pessoa idosa que vive sozinha e apresenta sinais de negligência e desnutrição, a conduta adequada da equipe é:', '["avaliar a situação de forma ampla, registrar, notificar a suspeita de violência conforme a legislação e articular a rede de proteção.","ignorar, por se tratar de questão familiar.","encaminhar a pessoa idosa imediatamente para uma instituição de longa permanência, sem consentimento.","aguardar que a própria pessoa idosa faça a denúncia.","registrar apenas os dados clínicos, sem considerar o contexto."]'::jsonb, 0, 'Negligência e abandono são formas de violência contra a pessoa idosa, de notificação compulsória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-493', 'tec', null, 'O Programa de Controle de Infecção Hospitalar baseia-se em diferentes tipos de precauções. As precauções padrão devem ser aplicadas:', '["no cuidado a todos os pacientes, independentemente do diagnóstico ou da suspeita de infecção, ao manipular sangue, fluidos corporais (exceto suor), pele não íntegra e mucosas.","apenas em pacientes com doenças infectocontagiosas confirmadas.","apenas em pacientes com HIV ou hepatite B.","apenas em pacientes colonizados por bactérias multirresistentes.","apenas em pacientes com suspeita de tuberculose ou sarampo."]'::jsonb, 0, 'As precauções padrão são universais e incluem higiene das mãos, EPI conforme o risco, descarte seguro de perfurocortantes e etiqueta respiratória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-494', 'tec', null, 'Além das precauções padrão, o programa de controle de infecção utiliza precauções baseadas na transmissão. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-495', 'tec', null, 'O programa de controle de infecção hospitalar reúne ações contínuas de prevenção e vigilância das infecções relacionadas à assistência à saúde. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-496', 'tec', null, 'Em relação aos riscos ocupacionais no serviço de saúde, é correto afirmar:', '["o risco biológico decorre do contato com sangue e secreções, exigindo o uso de equipamentos de proteção individual adequados.","o risco ergonômico decorre da exposição a agentes químicos manipulados na unidade.","o risco de acidente com perfurocortante é reduzido com o reencape da agulha antes do descarte.","o EPI é indicado somente após o contato com material biológico contaminado.","o risco biológico é eliminado com a simples organização dos móveis do ambiente."]'::jsonb, 0, 'O risco ergonômico está relacionado a postura, esforço físico e organização do trabalho; o reencape é proibido pela NR-32.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-497', 'tec', null, 'Durante a assistência, o técnico gera diferentes resíduos e precisa acondicioná-los conforme o gerenciamento de resíduos de serviços de saúde. Assinale a alternativa correta.', '["Os perfurocortantes são descartados em recipiente rígido, estanque e resistente à perfuração.","Os resíduos químicos são eliminados na rede de esgoto comum após o uso.","Os resíduos infectantes são acondicionados junto com os recicláveis.","Os resíduos do grupo A são acondicionados em saco branco leitoso e destinados à reciclagem.","Os perfurocortantes são descartados no lixo comum, junto aos resíduos administrativos."]'::jsonb, 0, 'Resíduos do grupo A (saco branco leitoso) seguem para tratamento; não vão para reciclagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-498', 'tec', null, 'As precauções padrão e específicas orientam as medidas adotadas no cuidado ao paciente conforme o modo de transmissão do agente infeccioso. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-499', 'tec', null, 'Durante a assistência a pacientes com doenças infecciosas, considera-se a cadeia de transmissão, composta por elementos que permitem a manutenção e a propagação do agente. Assinale a alternativa correta.', '["A interrupção de um dos elos da cadeia de transmissão contribui para o controle da doença infecciosa.","O hospedeiro suscetível é aquele que elimina o agente e o transmite aos demais.","A via de transmissão corresponde ao ambiente em que o agente se multiplica e se mantém.","A porta de entrada é o local pelo qual o agente é eliminado do organismo doente.","O reservatório é a via pela qual o agente deixa o hospedeiro e alcança o ambiente."]'::jsonb, 0, 'Elos: agente, reservatório, porta de saída, modo de transmissão, porta de entrada e hospedeiro suscetível.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-500', 'tec', null, 'O processamento de artigos odonto-médico-hospitalares é vital para a prevenção de infecções. Sobre os níveis de processamento, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-501', 'tec', null, 'A central de material e esterilização processa os artigos seguindo etapas que asseguram a limpeza e a esterilização adequadas. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-502', 'tec', null, 'Para que a esterilização por vapor saturado sob pressão (autoclave gravitacional) de instrumentais termorresistentes seja eficaz, um parâmetro de referência adequado é:', '["121 °C por 15 a 30 minutos, a cerca de 1 atm (15 psi) acima da pressão atmosférica.","100 °C por 60 minutos, à pressão ambiente.","134 °C por 10 minutos, a 2 atm, em autoclave gravitacional para qualquer carga.","60 °C por 2 horas.","30 minutos a 121 °C e 0,5 atm."]'::jsonb, 0, 'Os parâmetros exatos dependem do equipamento e da carga, mas 121 °C por 15 a 30 minutos é a referência clássica da autoclave gravitacional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-503', 'tec', null, 'Na Central de Material e Esterilização, a área onde ocorrem a recepção, a conferência e a limpeza dos materiais contaminados é chamada de:', '["área suja (expurgo).","área de preparo e acondicionamento.","área de armazenamento e distribuição.","área de esterilização.","área administrativa."]'::jsonb, 0, 'O fluxo deve ser unidirecional: da área suja para a área limpa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-504', 'tec', null, 'Na Central de Material e Esterilização, o profissional que trabalha no expurgo, realizando a limpeza manual de instrumentais, deve usar:', '["avental impermeável, luvas de borracha de cano longo, óculos ou protetor facial, máscara, gorro e calçado fechado impermeável.","apenas luvas de procedimento.","apenas jaleco de algodão.","máscara PFF2 e roupa comum.","nenhum EPI, pois o material ainda não foi esterilizado."]'::jsonb, 0, 'Há risco de respingos e de acidentes com perfurocortantes contaminados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
